sect2.example:
   Creazione di un Lazy Ghost


<?php
class Example
{
    public function __construct(public int $prop)
    {
        echo __METHOD__, "\n";
    }
}

$reflector = new ReflectionClass(Example::class);
$lazyObject = $reflector->newLazyGhost(function (Example $object) {
    // Inizializza l'oggetto sul posto
    $object->__construct(1);
});

var_dump($lazyObject);
var_dump(get_class($lazyObject));

// Attiva l'inizializzazione
var_dump($lazyObject->prop);
?>


   &example.outputs;


lazy ghost object(Example)#3 (0) {
  ["prop"]=>
  uninitialized(int)
}
string(7) "Example"
Example::__construct
int(1)

   Creazione di un Lazy Proxy


<?php
class Example
{
    public function __construct(public int $prop)
    {
        echo __METHOD__, "\n";
    }
}

$reflector = new ReflectionClass(Example::class);
$lazyObject = $reflector->newLazyProxy(function (Example $object) {
    // Crea e restituisce l'istanza reale
    return new Example(1);
});

var_dump($lazyObject);
var_dump(get_class($lazyObject));

// Attiva l'inizializzazione
var_dump($lazyObject->prop);
?>


   &example.outputs;


lazy proxy object(Example)#3 (0) {
  ["prop"]=>
  uninitialized(int)
}
string(7) "Example"
Example::__construct
int(1)
